from pathlib import Path
program='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Continue each diagonal run downward, preserving its color and slope.
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue
            for dc in (-1, 1):
                c2 = c + dc
                if 0 <= c2 < w and grid[r + 1][c2] == color:
                    rr, cc = r + 2, c + 2 * dc
                    while rr < h and 0 <= cc < w:
                        if out[rr][cc] == 0:
                            out[rr][cc] = color
                        rr += 1
                        cc += dc
    return out
'''
